\end{array}\right] \\
N^{-1} & =\left[\begin{array}{ll}
1 & 0 \\
0 & \frac{1}{2}
\end{array}\right]
\end{aligned}\)
Consider,
\(\begin{aligned}
\mathbf{N} \cdot \mathbf{M}^{10} \cdot \mathbf{N}^{-1} & =\left[\begin{array}{ll}
